    # Q3 -- angles from expressions; the bisector BP; the secondary does not bisect
    b3 = 3.0
    P3 = kite("ABCDO", b3 / T(R(30)), b3, b3 / T(R(20)), 12)
    P3["P"] = rot({"p": (-b3 * T(R(30)), 0.0)}, 12)["p"]
    l.q(3, u"$ABCD$ הוא דלתון שבו $AB=AD$ ו־$CB=CD$, ואלכסוניו $AC$ ו־$BD$ נפגשים ב־$O$. במעלות: $∠BAD=4x−100$, $∠BCD=x$ ו־$∠ABC=2x+50$. הקטע $BP$ חוצה את $∠ABD$, ו־$P$ על $AC$.", [
        I(u"א", u"נמקו מדוע $∠ADC=∠ABC$, ומצאו את $x$ ואת כל זוויות הדלתון.",
          u"$△ABC≅△ADC$ לפי צלע־צלע־צלע, ולכן $∠ADC=∠ABC=2x+50$. סכום הזוויות במרובע: $4x−100+x+2·(2x+50)=360$, כלומר $9x=360$ ו־$x=40$. הזוויות: $∠BAD=60°$, $∠BCD=40°$, $∠ABC=∠ADC=130°$.",
          [aeq("ADC", "ABC"), V(u"x", u"40"), A("BAD", 60), A("BCD", 40), A("ABC", 130)], space=60),
        I(u"ב", u"חשבו את $∠ABD$ ואת $∠CBD$.",
          u"האלכסון הראשי $AC$ חוצה את זווית הראש, ולכן $∠BAO=30°$, והוא מאונך ל־$BD$, ולכן $∠AOB=90°$. במשולש $△ABO$: $∠ABD=180°−90°−30°=60°$. מכאן $∠CBD=130°−60°=70°$.",
          [A("ABD", 60), A("CBD", 70)], space=50, on=(u"א",)),
        I(u"ג", u"תלמיד טוען: ״בדלתון כל אלכסון חוצה את הזוויות שבקצותיו, ולכן $BD$ חוצה את $∠ABC$.״ הפריכו את הטענה, וכתבו מה נכון לגבי חציית זוויות בדלתון.",
          u"לפי ב, $∠ABD=60°$ ו־$∠CBD=70°$, ולכן $BD$ אינו חוצה את $∠ABC$. בדלתון האלכסון הראשי חוצה את שתי זוויות הראש; האלכסון המשני חוצה את זוויות הצד רק כשהדלתון מעוין.",
          [V(u"הכרעה", u"הטענה שגויה")], space=50, on=(u"ב",)),
        I(u"ד", u"חשבו את $∠BPC$.",
          u"$∠ABP=\\f{60°}{2}=30°$. הזווית $∠BPC$ היא זווית חיצונית למשולש $△ABP$, ולכן $∠BPC=∠BAP+∠ABP=30°+30°=60°$.",
          [A("BPC", 60)], space=40, on=(u"ב",))],
        fig=fig(P3, "quad.kite+side-vertex-bisector-to-main-diagonal",
                segments=["AC", "BD", "BP"]),
        given=[eq("AB", "AD"), eq("CB", "CD"), col("APO"), col("AOC"), col("BOD"),
               aeq("ABP", "PBD"), u"הזוויות הנתונות בביטויים 4x−100, x, 2x+50 במעלות"])

    # Q4 -- Pythagoras chain 20/37/24; is the side angle right; altitude to a side
    P4 = {"A": (0.0, 16.0), "B": (-12.0, 0.0), "C": (0.0, -35.0), "D": (12.0, 0.0), "O": (0.0, 0.0)}
    P4["H"] = foot(P4["B"], P4["C"], P4["D"])
    l.q(4, u"$ABCD$ הוא דלתון שקודקודי הראש שלו $A$ ו־$C$. נתון $AB=20$ ס״מ, $CB=37$ ס״מ ו־$BD=24$ ס״מ. האלכסונים $AC$ ו־$BD$ נפגשים ב־$O$, והקטע $BH$ מאונך לצלע $CD$, כאשר $H$ על $CD$, כלומר $BH⊥CH$.", [
        I(u"א", u"חשבו את אורך האלכסון $AC$. נמקו כל שלב, ואל תניחו ש־$O$ הוא אמצע $AC$.",
          u"בדלתון האלכסון הראשי $AC$ מאונך ל־$BD$ וחוצה אותו, ולכן $BO=12$ ס״מ והמשולשים $△ABO$, $△CBO$ ישרי זווית ב־$O$. לפי פיתגורס $AO=\\sqrt{400−144}=16$ ס״מ ו־$OC=\\sqrt{1369−144}=35$ ס״מ. לכן $AC=51$ ס״מ.",
          [F("AC", 51)], space=60),
        I(u"ב", u"חשבו את שטח הדלתון ואת היקפו.",
          u"השטח הוא מחצית מכפלת האלכסונים: $\\f{51·24}{2}=612$ סמ״ר. ההיקף: $2·20+2·37=114$ ס״מ.",
          [Area("ABCD", 612), Per("ABCD", 114)], space=40, on=(u"א",)),
        I(u"ג", u"האם $∠ABC$ ישרה? נמקו. חשבו את שטח הדלתון בדרך נוספת, בעזרת המשולשים $△ABC$ ו־$△ADC$.",
          u"לא. אילו $∠ABC$ הייתה ישרה, לפי פיתגורס היה מתקיים $AB^2+BC^2=AC^2$, אבל $AB^2+BC^2=400+1369=1769$ ואילו $AC^2=2601$. דרך נוספת לשטח: $BO$ הוא הגובה של $△ABC$ לבסיס $AC$, ולכן שטחו $\\f{51·12}{2}=306$ סמ״ר; $△ADC$ חופף לו, ושטח הדלתון $2·306=612$ סמ״ר.",
          [V(u"האם ABC ישרה", u"לא"), V(u"שטח בדרך נוספת", u"612", CM2)], space=60, on=(u"א",)),
        I(u"ד", u"חשבו את אורך הגובה $BH$.",
          u"שטח $△BCD$ הוא $\\f{BD·OC}{2}=\\f{24·35}{2}=420$ סמ״ר. גם $\\f{CD·BH}{2}=420$, ולכן $BH=\\f{840}{37}$ ס״מ.",
          [F("BH", "840/37")], space=50, on=(u"א",))],
        fig=fig(P4, "quad.kite+altitude-to-side",
                segments=["AC", "BD", "BH"], right=["BHC"]),
        given=[sh("kite", "ABCD"), ln("AB", 20), ln("CB", 37), ln("BD", 24),
               col("AOC"), col("BOD"), col("CHD"), perp("BH", "CD"),
               dict(type="perpendicular", at="H", of=["BH", "CH"])])

    # Q5 -- a kite from a reflection; perpendicular diagonals: kite iff one bisects the other
    P5 = rot({"P": (0.0, 6.0), "Q": (-5.0, 0.0), "R": (0.0, -10.0), "S": (5.0, 0.0)}, 28)
    l.q(5, u"הנקודה $S$ היא תמונת השיקוף של הנקודה $Q$ בישר $PR$, והנקודות $P$ ו־$R$ נמצאות על הישר הזה משני צדי הקטע $QS$. בשרטוט המרובע $PQRS$ והקטעים $PR$ ו־$QS$.", [
        I(u"א", u"הוכיחו ש־$PQRS$ הוא דלתון, וקבעו את קודקודי הראש ואת האלכסון הראשי שלו.",
          u"השיקוף בישר $PR$ משאיר את $P$ ואת $R$ במקומן ומעביר את $Q$ ל־$S$, והוא שומר על אורכים. לכן $PQ=PS$ ו־$RQ=RS$: שני זוגות נפרדים של צלעות סמוכות שוות. הקטע $QS$ מאונך לציר $PR$ ונחצה על ידו, ו־$P$, $R$ משני צדי $QS$, ולכן האלכסונים נחתכים בתוך המרובע והוא קמור. זהו דלתון שקודקודי הראש שלו $P$ ו־$R$, והאלכסון הראשי $PR$.",
          [eq("PQ", "PS"), eq("RQ", "RS"), sh("kite", "PQRS"), V(u"קודקודי הראש", u"P, R")], space=70),
        I(u"ב", u"הוכיחו: במרובע קמור שאלכסוניו מאונכים, שתי צלעות סמוכות שוות זו לזו אם ורק אם האלכסון שיוצא מהקודקוד המשותף להן חוצה את האלכסון האחר. הסיקו: מרובע קמור שאלכסוניו מאונכים הוא דלתון אם ורק אם אחד מאלכסוניו חוצה את האחר.",
          u"נקודת החיתוך מחלקת את אחד האלכסונים לקטעים $a$ ו־$c$, ואת האחר לקטעים $b$ ו־$d$. שתי הצלעות שנפגשות בקצה הקטע $b$ הן יתרים במשולשים ישרי זווית, ולפי פיתגורס אורכיהן $\\sqrt{a^2+b^2}$ ו־$\\sqrt{c^2+b^2}$. הן שוות אם ורק אם $a^2=c^2$, כלומר $a=c$: האלכסון שעובר דרך הקודקוד המשותף חוצה את האחר. אותו תנאי בדיוק נותן גם את זוג הצלעות שנפגשות בקצה הקטע $d$. לכן אם אלכסון אחד חוצה את האחר, יש שני זוגות נפרדים של צלעות סמוכות שוות, והמרובע דלתון; ואם המרובע דלתון, זוג הצלעות השוות שנפגשות בקודקוד ראש מחייב שהאלכסון היוצא ממנו יחצה את האחר.",
          [V(u"הכללה", u"אלכסונים מאונכים: דלתון אם ורק אם אלכסון אחד חוצה את האחר")], space=90),
        I(u"ג", u"הוכיחו: אם במרובע קמור האלכסונים אינם מאונכים זה לזה, המרובע אינו דלתון, גם אם אחד האלכסונים חוצה את האחר.",
          u"בכל דלתון האלכסון הראשי מאונך למשני: מחפיפת שני המשולשים שהאלכסון הראשי יוצר, לפי צלע־צלע־צלע, הוא חוצה את זווית הראש; במשולש השווה־שוקיים שבסיסו האלכסון המשני חוצה זווית הראש הוא גם גובה. לכן מרובע שאלכסוניו אינם מאונכים אינו דלתון, בכל בחירה של זוגות הצלעות; חציית אלכסון אינה משנה זאת.",
          [V(u"טענה", u"דלתון מחייב אלכסונים מאונכים")], space=70)],
        fig=fig(P5, "quad.kite-by-reflection", polygons=["PQRS"], segments=["PR", "QS"]),
        given=[u"S היא תמונת השיקוף של Q בישר PR; P ו־R משני צדי QS"])

    # Q6 -- construction from words: main diagonal, a side and where the diagonals meet
    q6 = l.q(6, u"בשאלה זו אין שרטוט. יש לבנות דלתון $KLMN$ שקודקודי הראש שלו $K$ ו־$M$, לפי הנתונים: האלכסון הראשי $KM=10$ ס״מ, $KL=5$ ס״מ, והאלכסונים נפגשים בנקודה $S$ שעל $KM$ כך ש־$KS=3$ ס״מ.", [
        I(u"א", u"תכננו את הבנייה: הסבירו מדוע $LN⊥KM$ ומדוע $S$ היא אמצע $LN$, וחשבו את אורך האלכסון המשני $LN$.",
          u"בדלתון האלכסון הראשי $KM$ מאונך לאלכסון המשני $LN$ וחוצה אותו: $△KLM≅△KNM$ לפי צלע־צלע־צלע, ולכן $KM$ חוצה את $∠LKN$, ובמשולש השווה־שוקיים $△KLN$ חוצה זווית הראש הוא גם תיכון וגם גובה. במשולש הישר־זווית $△KSL$: $LS=\\sqrt{25−9}=4$ ס״מ, ולכן $LN=8$ ס״מ.",
          [F("LN", 8), V(u"הצדקת הבנייה", u"KM האנך האמצעי של LN")], space=70),
        I(u"ב", u"חשבו את $ML$ ואת שטח הדלתון. האם $∠KLM$ ישרה? נמקו.",
          u"$SM=10−3=7$ ס״מ, ולפי פיתגורס $ML=\\sqrt{49+16}=\\sqrt{65}$ ס״מ. השטח: $\\f{10·8}{2}=40$ סמ״ר. אילו $∠KLM$ הייתה ישרה, היה מתקיים $KL^2+LM^2=KM^2$; אבל $25+65=90$ ואילו $KM^2=100$. לכן הזווית אינה ישרה.",
          [F("ML", "sqrt(65)"), Area("KLMN", 40), V(u"האם KLM ישרה", u"לא")], space=70, on=(u"א",)),
        I(u"ג", u"בנו את הדלתון במקום הריק שלמטה, בסרגל, במחוגה ובמשולש. סמנו בסימון אחד את הנתונים, ובסימון אחר את מה שהסקתם.",
          u"בונים קטע $KM=10$ ס״מ ומסמנים עליו את $S$ במרחק $3$ ס״מ מ־$K$. מעבירים דרך $S$ ניצב ל־$KM$. מעגל שמרכזו $K$ ורדיוסו $5$ ס״מ חותך את הניצב משני צדי $KM$ בנקודות $L$ ו־$N$. מחברים $K$, $L$, $M$, $N$. הנתונים מסומנים בנפרד מן המסקנות $LS=SN=4$ ס״מ ו־$ML=MN$.",
          [V(u"בנייה", u"KM=10, KS=3, ניצב ב־S, מעגל 5 סביב K")],
          make=[poly("KLMN"), seg("KM"), seg("LN")], on=(u"א",))])
    words(q6, [poly("KLMN"), seg("KM"), seg("LN"), dict(type="point", point="S"),
               u"האלכסון הראשי KM=10 ס״מ, KL=5 ס״מ, האלכסונים נפגשים ב־S ו־KS=3 ס״מ"], space=250)

    # Q7 -- existence and planning: sides 5 and 6
    q7 = l.q(7, u"בשאלה זו אין שרטוט. תמר רוצה לבנות דלתון $ABCD$ שבו $AB=AD=5$ ס״מ ו־$CB=CD=6$ ס״מ.", [
        I(u"א", u"תמר בחרה שאורך האלכסון המשני יהיה $11$ ס״מ. הוכיחו שאין דלתון כזה.",
          u"האלכסון המשני הוא $BD$, הקטע שבין קודקודי הצד. במשולש $△ABD$ היה מתקיים $AB+AD=10<11$, בסתירה לאי־שוויון המשולש. לכן אין דלתון כזה.",
          [V(u"קיום", u"אין דלתון כזה")], space=50),
        I(u"ב", u"מצאו את כל האורכים האפשריים של האלכסון המשני, ונמקו מדוע לכל אורך כזה אכן יש דלתון.",
          u"כדי שיהיה משולש $△ABD$ צריך $BD<10$, וכדי שיהיה משולש $△CBD$ צריך $BD<12$. לכן $0<BD<10$ ס״מ. לכל אורך כזה בונים את $BD$, ועל האנך האמצעי שלו בוחרים את $A$ במרחק $5$ ס״מ מ־$B$ ואת $C$ במרחק $6$ ס״מ מ־$B$, משני צדי $BD$. כך $AB=AD$ ו־$CB=CD$, והמרובע קמור.",
          [V(u"תחום BD", u"0<BD<10", CM)], space=70, on=(u"א",)),
        I(u"ג", u"תמר בחרה כעת שאורך האלכסון המשני יהיה $8$ ס״מ. חשבו את אורך האלכסון הראשי. האם $∠ABC$ ישרה? נמקו.",
          u"האלכסון הראשי $AC$ חוצה את $BD$ ומאונך לו בנקודה $O$, ולכן $BO=4$ ס״מ. לפי פיתגורס $AO=\\sqrt{25−16}=3$ ס״מ ו־$OC=\\sqrt{36−16}=2\\sqrt{5}$ ס״מ, ולכן $AC=3+2\\sqrt{5}$ ס״מ. $AB^2+BC^2=25+36=61$, ואילו $AC^2=9+12\\sqrt{5}+20=29+12\\sqrt{5}$. השוויון היה מחייב $12\\sqrt{5}=32$, אבל $720<1024$, כלומר $12\\sqrt{5}<32$. לכן לפי פיתגורס הזווית אינה ישרה.",
          [F("AC", "3+2*sqrt(5)"), V(u"האם ABC ישרה", u"לא")], space=80, on=(u"ב",)),
        I(u"ד", u"בנו את הדלתון של סעיף ג במקום הריק שלמטה, בסרגל ובמחוגה. התחילו מן האלכסון המשני, וסמנו בנפרד את הנתונים ואת מה שחישבתם.",
          u"בונים $BD=8$ ס״מ. קשתות ברדיוס $5$ ס״מ סביב $B$ ו־$D$ נחתכות ב־$A$; קשתות ברדיוס $6$ ס״מ סביב $B$ ו־$D$ נחתכות ב־$C$ בצד השני של $BD$. מחברים את הקודקודים. מסמנים בנפרד את הנתונים ואת המסקנה על אורך $AC$.",
          [V(u"בנייה", u"BD=8; קשתות 5 ל־A וקשתות 6 ל־C")],
          make=[poly("ABCD"), seg("BD"), seg("AC")], on=(u"ג",))])
    words(q7, [poly("ABCD"), seg("BD"), seg("AC"), eq("AB", "AD"), eq("CB", "CD"),
               u"AB=AD=5 ס״מ ו־CB=CD=6 ס״מ"], space=250)

